// Normalize field names and preserve literal E.164 plus the complete property context.
const body = $input.first().json.body || $input.first().json;
const leads = Array.isArray(body) ? body : [body];
const best = new Map();
const order = [];

for (const raw of leads) {
  const rawPhone = String(raw.phone || raw.whatsapp || raw.mobile || '').trim();
  const digits = rawPhone.replace(/\D/g, '');
  const candidate = rawPhone.startsWith('+') ? '+' + digits : (/^[1-9]\d{7,14}$/.test(rawPhone) ? '+' + rawPhone : null);
  const identity_phone = candidate && /^\+[1-9]\d{7,14}$/.test(candidate) ? candidate : null;
  const lead = {
    phone: identity_phone,
    identity_phone,
    email: raw.email ? String(raw.email).trim().toLowerCase() : null,
    name: raw.name || raw.pushName || null,
    message: raw.message || '',
    listing_id: raw.listing_id || raw.property_id || null,
    property_public_id: raw.property_public_id || raw.eb_code || null,
    property_title: raw.property || raw.title || raw.address || 'Propiedad sin titulo',
    operation_type: raw.operation_type || raw.operation || raw.listing_type || '',
    property_zone: raw.property_zone || raw.zone || raw.address || '',
    property_price: raw.property_price || raw.price || 'Precio por confirmar',
    easybroker_url: raw.easybroker_url || null,
    scraper_lead_id: raw.lead_id || raw.id || null,
    source_tab: raw.source_tab || 'mensajes',
    source: 'inmuebles24',
  };
  const key = lead.scraper_lead_id
    ? 'id:' + lead.scraper_lead_id
    : 'contact:' + (lead.identity_phone || lead.email || 'unknown') + ':' + (lead.listing_id || 'unknown');
  const score = (item) => (item.identity_phone ? 2 : 0) + (item.email ? 1 : 0) + (item.listing_id ? 1 : 0);
  if (!best.has(key)) {
    best.set(key, lead);
    order.push(key);
  } else if (score(lead) > score(best.get(key))) {
    best.set(key, lead);
  }
}

return order.map((key) => ({ json: best.get(key) }));

const dbRows = $input.all();
const leads = $('Split & Normalize Leads').all();
const out = [];

for (let index = 0; index < dbRows.length; index += 1) {
  const db = dbRows[index].json;
  const lead = (leads[index] || leads[0]).json;
  const isDay = db.is_day === true;
  const isReturning = Boolean(db.existing_conv_id);
  const sameProperty = db.same_property === true;

  if (!lead.identity_phone) {
    out.push({ json: { ...lead, route: 'non_routable', reason: 'invalid_or_missing_e164_phone' } });
    continue;
  }
  // Silent capture applies before any returning-lead behavior.
  if (!isDay) {
    out.push({ json: { ...lead, route: 'night_queue', is_returning: isReturning } });
    continue;
  }
  if (isReturning && sameProperty) {
    out.push({ json: {
      ...lead,
      route: 'returning_same',
      existing_conv_id: db.existing_conv_id,
      assigned_agent_id: db.assigned_agent_id,
      existing_mode: db.existing_mode,
    } });
    continue;
  }
  out.push({ json: { ...lead, route: 'day_auction', is_returning: isReturning } });
}

return out;

const lead = $('Route Decision').item.json;
const conversation = $input.item.json;
if (!lead.assigned_agent_id) return [{ json: { skip: true } }];
return [{ json: {
  agent_id: lead.assigned_agent_id,
  conversation_id: conversation.conversation_id,
  lead_name: lead.name || lead.identity_phone || 'No disponible',
  lead_phone: lead.identity_phone || 'No disponible',
  property_title: lead.property_title || 'No disponible',
  operation_type: lead.operation_type || lead.operation || 'No disponible',
  property_zone: lead.property_zone || lead.zone || 'No disponible',
  property_price: lead.property_price || lead.price || 'No disponible',
  property_public_id: lead.property_public_id || lead.property_id || 'No disponible',
  easybroker_url: lead.easybroker_url || lead.url || 'No disponible',
} }];

